import type { HierarchyRectangularNode } from '@visx/hierarchy/lib/types.js';
import React, { forwardRef, useEffect, useState } from 'react';

import { headerText, valueChip } from './TreeMapTooltip.sty.js';
import { mergeTooltipActions } from '../../../core/components/series-action/functions/mergeTooltipActions.js';
import { useChartActionsMenu } from '../../../core/components/series-action/hooks/useChartActionsMenu.js';
import { ChartTooltip } from '../../../core/components/tooltip/ChartTooltip/ChartTooltip.js';
import { TooltipText } from '../../../core/components/tooltip/section-components/atoms/TooltipText.js';
import { TooltipBody } from '../../../core/components/tooltip/section-components/TooltipBody.js';
import { TooltipHeader } from '../../../core/components/tooltip/section-components/TooltipHeader.js';
import { TooltipInfoContent } from '../../../core/components/tooltip/section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../../core/components/tooltip/section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../../core/components/tooltip/section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../../../core/components/tooltip/section-components/TooltipValueContent.js';
import { useTooltipSeriesActions } from '../../../core/components/tooltip/shared/hooks/useTooltipSeriesActions.js';
import { SingleDataPointShape } from '../../../core/components/tooltip-atoms/shapes/SingleDataPointShape.js';
import { safeGet } from '../../../core/functions/safe-get.js';
import { TooltipItem as TooltipItemType } from '../../../core/types/tooltip.js';
import { useFormatter } from '../../context/FormatterContext.js';
import { useTreeMapData } from '../../context/TreeMapDataContext.js';
import { getTooltipItem } from '../../functions/get-tooltip-item.js';
import { useTruncationMode } from '../../hooks/useTruncationMode.js';
import { useOverlayState, useTooltipState } from '../../store/selectors.js';
import type {
  InternalTreeMapClusterNode,
  InternalTreeMapLeafNode,
  TreeMapMetadata,
} from '../../types/internal.js';

interface TreeMapTooltipProps {
  metadata: TreeMapMetadata;
}

export const TreeMapTooltip = forwardRef<HTMLDivElement, TreeMapTooltipProps>(
  ({ metadata }, forwardedRef) => {
    const [tooltipContent, setTooltipContent] = useState<
      HierarchyRectangularNode<InternalTreeMapLeafNode> | undefined
    >();
    const formatter = useFormatter();
    const { metadataSeries, metadataMap } = metadata;

    const { visible, pinned, content, position } = useTooltipState();
    const { mouseInBounds } = useOverlayState();

    const truncationMode = useTruncationMode();
    const data = useTreeMapData();
    const { unit } = data;

    const {
      selectedItem: selectedItemId,
      actionsMenuRef,
      updateSelectedItem,
      onLeave,
    } = useChartActionsMenu();

    useEffect(() => {
      if (!pinned && content) {
        setTooltipContent(content);
      }
    }, [content, pinned]);

    const seriesActions = useTooltipSeriesActions<InternalTreeMapClusterNode>(
      metadataSeries,
      (nodeData) => safeGet(metadataMap, nodeData).id,
    );

    /**
     * Tooltip will rerender to get the mouse position only if
     * the following requirement is fulfilled
     */
    const showTooltip = pinned || (mouseInBounds && visible);

    const item: TooltipItemType = getTooltipItem(
      formatter,
      tooltipContent,
      unit,
    );

    if (!showTooltip || !position || !tooltipContent) {
      return null;
    }

    const seriesActionsCallback = mergeTooltipActions(item, seriesActions);

    const nodeColor = tooltipContent.parent?.data.color?.Default ?? '';

    return (
      <ChartTooltip
        ref={forwardedRef}
        pinned={pinned}
        position={position}
        onMouseLeave={onLeave}
        actionSelectionValue={{
          selectedItemId,
          actionsMenuRef,
          updateSelectedItem,
        }}
      >
        <TooltipHeader>
          <TooltipText truncationMode={truncationMode} className={headerText}>
            {tooltipContent.parent?.data.name}
          </TooltipText>
        </TooltipHeader>
        <TooltipBody virtualization={false}>
          <TooltipItem actions={seriesActionsCallback}>
            <TooltipSymbolContent>
              <SingleDataPointShape color={nodeColor} />
            </TooltipSymbolContent>
            <TooltipInfoContent>
              <TooltipText truncationMode={truncationMode}>
                {item.name}
              </TooltipText>
            </TooltipInfoContent>
            <TooltipValueContent variant="chip">
              <span className={valueChip}>{item.values?.[0]}</span>
            </TooltipValueContent>
          </TooltipItem>
        </TooltipBody>
      </ChartTooltip>
    );
  },
);
